async function invokeGoogleCalendar(action,payload={}){
  const {data,error}=await supabase.functions.invoke('nexlab-google-calendar',{body:{action,...payload}});
  if(error){
    let message=error?.message||'Não foi possível acessar a integração do Google Calendar.';
    try{const body=await error?.context?.json?.();message=body?.message||body?.error||message;}catch{}
    throw new Error(message);
  }
  if(data?.ok===false&&!data?.partial)throw new Error(data?.message||data?.error||'A integração do Google Calendar recusou a solicitação.');
  return data||{};
}
